int wmain(int argc,wchar_t**argv){if(argc==4&&!wcscmp(argv[1],L"--worker"))return worker((uintptr_t)wcstoull(argv[2],NULL,10),(unsigned)wcstoul(argv[3],NULL,10));WNDCLASSW c={.lpfnWndProc=procedure,.hInstance=GetModuleHandleW(NULL),.lpszClassName=L"MaxSpinWindowContract"};CHECK(RegisterClassW(&c));HWND parent=CreateWindowW(c.lpszClassName,L"Max Spin window contract",WS_OVERLAPPEDWINDOW,50,50,640,360,NULL,NULL,c.hInstance,NULL);CHECK(parent&&created==1);ShowWindow(parent,SW_SHOW);ShowWindow(parent,SW_SHOWNORMAL);wchar_t exe[32768];CHECK(GetModuleFileNameW(NULL,exe,32768));for(unsigned i=0;i<2;i++){wchar_t cmd[33000];swprintf(cmd,33000,L"\"%ls\" --worker %llu %u",exe,(unsigned long long)(uintptr_t)parent,i);STARTUPINFOW startup={.cb=sizeof startup};PROCESS_INFORMATION child;CHECK(CreateProcessW(exe,cmd,NULL,NULL,FALSE,0,NULL,NULL,&startup,&child));CloseHandle(child.hThread);for(;;){DWORD result=MsgWaitForMultipleObjects(1,&child.hProcess,FALSE,30000,QS_ALLINPUT);if(result==WAIT_OBJECT_0)break;CHECK(result==WAIT_OBJECT_0+1);MSG msg;while(PeekMessageW(&msg,NULL,0,0,PM_REMOVE)){TranslateMessage(&msg);DispatchMessageW(&msg);}}DWORD code;CHECK(GetExitCodeProcess(child.hProcess,&code)&&code==0);CloseHandle(child.hProcess);printf("WINDOW alive=%d visible=%d iconic=%d creates=%u destroys=%u\n",IsWindow(parent),IsWindowVisible(parent),IsIconic(parent),created,destroyed);CHECK(IsWindow(parent)&&IsWindowVisible(parent)&&!IsIconic(parent)&&created==1&&destroyed==0);}DestroyWindow(parent);CHECK(destroyed==1);puts("PASS one HWND, two real presenting Vulkan workers, no minimize or recreation");return 0;}
